 using System.ComponentModel;
 using System.Text.Json;
 using Microsoft.Extensions.Logging;
 using ModelContextProtocol.Server;

 namespace ApiMcpServer.Tools;

 /// <summary>
 /// MCP tools that wrap the Open-Meteo REST API.
 /// Uses constructor injection — the SDK resolves HttpClient via DI
 /// and does NOT expose it in the tool schema.
 /// </summary>
 [McpServerToolType]
 public class WeatherApiTools(HttpClient httpClient, ILogger<WeatherApiTools> logger)
 {
     private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

     [McpServerTool(ReadOnly = true), Description("Get current weather for a location by latitude and longitude.")]
     public async Task<string> GetCurrentWeather(
         [Description("Latitude of the location (e.g. 47.6)")] double latitude,
         [Description("Longitude of the location (e.g. -122.3)")] double longitude,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Fetching weather for ({Lat}, {Lon})", latitude, longitude);

         var url = $"https://api.open-meteo.com/v1/forecast"
                 + $"?latitude={latitude}&longitude={longitude}"
                 + $"&current=temperature_2m,wind_speed_10m,relative_humidity_2m";

         var response = await httpClient.GetAsync(url, cancellationToken);
         response.EnsureSuccessStatusCode();

         using var doc = await JsonDocument.ParseAsync(
             await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

         var current = doc.RootElement.GetProperty("current");
         var result = new
         {
             temperature_c = current.GetProperty("temperature_2m").GetDouble(),
             wind_speed_kmh = current.GetProperty("wind_speed_10m").GetDouble(),
             humidity_pct = current.GetProperty("relative_humidity_2m").GetDouble()
         };

         return JsonSerializer.Serialize(result, JsonOptions);
     }

     [McpServerTool(ReadOnly = true), Description("Get a 7-day daily temperature forecast for a location.")]
     public async Task<string> GetForecast(
         [Description("Latitude of the location")] double latitude,
         [Description("Longitude of the location")] double longitude,
         CancellationToken cancellationToken = default)
     {
         var url = $"https://api.open-meteo.com/v1/forecast"
                 + $"?latitude={latitude}&longitude={longitude}"
                 + $"&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

         var response = await httpClient.GetAsync(url, cancellationToken);
         response.EnsureSuccessStatusCode();

         var json = await response.Content.ReadAsStringAsync(cancellationToken);
         return json;
     }
 }

